# Ejercicio T2-02 · La accuracy de un detector
# reales y predichas son dos listas de la misma longitud: la clase real y la que dijo el modelo.
# Cuenta en cuántas posiciones coinciden y divide entre el total.

def accuracy(reales, predichas):
    aciertos = 0
    for r, p in zip(reales, predichas):
        if r == p:
            aciertos = aciertos   # ← cambia esta línea: suma un acierto
    return aciertos / len(reales)

# El «detector» que dice siempre normal, con 3 clientes. Debería imprimir 0.6666666666666666:
print(accuracy(["normal", "abuso", "normal"], ["normal", "normal", "normal"]))
